package com.aoo.bcg.version;
import org.junit.jupiter.api.Test;import java.time.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;import static com.aoo.bcg.version.VersionModels.*;
final class VersionServiceTest {
 @Test void minimumVersionForcesUpgradeAndReturnsSignedManifest(){var release=new Release(7,"2.2.0","2.0.0",false,100,"1.9.8","https://cdn.example/v2");var manifest=new Manifest(8,"2.2.0","a".repeat(64),"Ed25519","release-key-7","detached-signature",List.of(new Asset("main.js",12,"b".repeat(64))));var repo=new Stub(release,manifest);Decision d=new VersionService(repo,Clock.fixed(Instant.parse("2026-08-24T00:00:00Z"),ZoneOffset.UTC)).check(new Request("ios","stable","1.8.9","1.8.9","device-1",null));assertEquals("FORCE_UPDATE",d.status());assertTrue(d.forceUpdate());assertEquals("detached-signature",d.manifest().signature());assertEquals("1.9.8",d.release().rollbackVersion());assertTrue(d.featureFlags().getFirst().enabled());assertEquals(10,d.directory().selectedServerId());}
 @Test void semanticVersionsAreComparedNumerically(){assertTrue(VersionService.compare("2.10.0","2.9.9")>0);assertThrows(IllegalArgumentException.class,()->VersionService.compare("2.beta","2.0"));}
 private record Stub(Release release,Manifest signed) implements VersionRepository {public Optional<Release> eligibleRelease(String p,String c,int b,Instant n){return Optional.of(release);}public Optional<Release> rollback(String p,String c,String v){return Optional.of(release);}public List<Notice> notices(String p,String c,Instant n){return List.of();}public Optional<Maintenance> maintenance(String p,String c,Instant n){return Optional.empty();}public Optional<Manifest> manifest(long id){return Optional.of(signed);}public List<FeatureFlag> featureFlags(String p,String c,int b,Instant n){return List.of(new FeatureFlag("wallet",true,"{}"));}public Directory directory(String p,String c,int b,Long preferred,Instant n){return new Directory(4,List.of(new ServerNode(10,"s10","一区","cn","wss://s10","ACTIVE",100,null,null)),10L);}}
}
